const eras=[
 {id:'origen',number:'01 / 04',title:'El ideal',accent:'se construye.',lede:'Antes de las cifras hubo jerarquías: qué cuerpos se admiraban, quiénes podían encarnarlos y a quiénes se les exigía otra cosa.',icon:'✳',aside:'La belleza también cuenta una historia social.',events:[
  {id:'abundancia',year:'S. XVI–XVIII',title:'La abundancia como signo de posición',summary:'En ciertos contextos de las élites europeas, un cuerpo más voluminoso podía asociarse con acceso a alimentos y riqueza.',body:'No existió una época universal en la que «la gordura era el ideal». La valoración corporal variaba según el lugar, la clase y el género. Este contraste sirve para mostrar que lo que hoy parece natural siempre tuvo una historia.',why:'La pregunta cambia: ¿quién tiene el poder de definir qué cuerpo merece admiración?',sources:[['Strings · NYU Press','https://nyupress.org/9781479831098/fearing-the-black-body/']]},
  {id:'racializacion',year:'S. XVIII–XIX',title:'La delgadez se vuelve una distinción',summary:'Los ideales europeos de belleza también se cruzaron con jerarquías raciales y de clase.',body:'Sabrina Strings reconstruye cómo ciertos discursos occidentales ligaron la delgadez con autocontrol y superioridad moral, y la gordura con estereotipos raciales. Su investigación no pretende explicar todas las culturas, pero sí muestra que la gordofobia tiene raíces históricas más profundas que una recomendación de salud.',why:'La norma corporal no pesa igual sobre todos los cuerpos.',sources:[['Strings · Introducción','https://nyupress.org/blog/2020/01/27/fearing-the-black-body-introduction/']]},
  {id:'quetelet',year:'S. XIX',title:'El “hombre medio” entra en escena',summary:'Adolphe Quetelet propone una relación matemática entre peso y altura para describir poblaciones.',body:'La fórmula que luego conoceríamos como IMC surgió en el siglo XIX dentro de la estadística social. Su origen no fue una medida personalizada de belleza ni una explicación completa de la salud de cada persona.',why:'Una media estadística puede transformarse, con el tiempo, en una expectativa individual.',sources:[['Revisión histórica del IMC','https://pmc.ncbi.nlm.nih.gov/articles/PMC11611441/']]}
 ]},
 {id:'cifras',number:'02 / 04',title:'El cuerpo',accent:'se mide.',lede:'El siglo XX convierte la relación con el cuerpo en un conjunto de números, tablas y programas.',icon:'↗',aside:'Una cifra parece neutral. Sus usos sociales no siempre lo son.',events:[
  {id:'calorias',year:'1918',title:'Un libro para contar calorías',summary:'Lulu Hunt Peters publica Diet and Health; With Key to the Calories.',body:'El libro populariza el uso cotidiano de las calorías para organizar la alimentación y el peso. Peters no inventó el concepto científico de caloría: lo acercó a la vida doméstica como una herramienta de cálculo corporal.',why:'Comer empieza a narrarse también en números.',sources:[['Edición de 1918 · UPenn','https://onlinebooks.library.upenn.edu/webbin/book/lookupid?key=olbp62668']]},
  {id:'tablas',year:'1942',title:'Tablas de “peso ideal”',summary:'Metropolitan Life publica tablas que vinculan peso y altura con un “ideal”.',body:'Las tablas se basaban en poblaciones aseguradas y en asociaciones con mortalidad. Con el tiempo circularon más allá de ese contexto y contribuyeron a presentar ciertos rangos como metas generales. El lenguaje cambió luego a “peso deseable”.',why:'¿Qué sucede cuando una referencia de seguros se convierte en norma cotidiana?',sources:[['Revisión histórica · NIH','https://pmc.ncbi.nlm.nih.gov/articles/PMC4904092/']]},
  {id:'weightwatchers',year:'1963',title:'La dieta se vuelve programa',summary:'Jean Nidetch funda Weight Watchers y convierte la pérdida de peso en una experiencia comercial grupal.',body:'La propuesta combina seguimiento, reuniones y apoyo entre participantes. En esta historia, el hito importa por la consolidación de un mercado que organiza el deseo de modificar el cuerpo mediante servicios, métodos y pertenencia.',why:'La búsqueda de un cuerpo ideal ya no es solo una idea: también puede contratarse.',sources:[['Historia de WW','https://www.weightwatchers.com/ca/en/blog/celebrating-wws-founder-jean-nidetch']]},
  {id:'imc',year:'1972',title:'El índice recibe un nuevo nombre',summary:'Ancel Keys y colaboradores rebautizan la fórmula de Quetelet como “índice de masa corporal”.',body:'El IMC se vuelve una referencia muy difundida para estudiar poblaciones. Su historia recuerda que una herramienta estadística tiene límites y no describe por sí sola la salud, las experiencias ni el valor de una persona.',why:'Un nombre técnico puede darle a una cifra una autoridad mucho mayor en la vida diaria.',sources:[['Historia y límites del IMC','https://pmc.ncbi.nlm.nih.gov/articles/PMC11611441/']]}
 ]},
 {id:'disputa',number:'03 / 04',title:'El ideal',accent:'se discute.',lede:'La imagen de la extrema delgadez crece en los medios; después aparecen campañas y movimientos que le responden.',icon:'“',aside:'Las imágenes dominantes conviven con formas de resistencia.',events:[
  {id:'heroinchic',year:'AÑOS 90',title:'La estética heroin chic',summary:'La moda instala una imagen de fragilidad y extrema delgadez en campañas y editoriales.',body:'Es un ejemplo visible de cómo la moda y los medios pueden convertir una apariencia en aspiración. El término fue debatido públicamente en 1997; no representa a toda la década ni explica por sí solo la relación de las mujeres con sus cuerpos.',why:'Un ideal aparece como estilo, pero también enseña qué tipo de cuerpo recibe visibilidad.',sources:[['Registro de la época · 1997','https://www.worldwidewords.org/tp-her1.html']]},
  {id:'dove',year:'2004',title:'La publicidad empieza a discutir la belleza',summary:'La campaña Belleza Real de Dove pone cuerpos diversos en anuncios.',body:'Es un cambio reconocible dentro de la industria publicitaria. También abre una tensión útil para el proyecto: la diversidad puede ser reivindicación y, al mismo tiempo, parte de una estrategia de marca. La campaña no equivale al origen del activismo corporal.',why:'El mercado puede vender tanto la exigencia como la respuesta a esa exigencia.',sources:[['Historia de la campaña · Dove','https://www.dove.com/us/es/stories/about-dove/breaking-down-narrow-beauty-stereotypes.html']]},
  {id:'bodypositive',year:'AÑOS 2010',title:'Más voces, más cuerpos',summary:'El body positive y el activismo antigordofóbico ganan visibilidad en redes.',body:'Mujeres, creadoras y activistas cuestionan la exclusión de ciertos cuerpos, comparten experiencias y exigen otras representaciones. Esa conversación amplía el imaginario, aunque no borra automáticamente la presión por adelgazar ni llega igual a todos los espacios.',why:'La disputa por la representación se vuelve cotidiana y participativa.',sources:[['El País · 2017','https://elpais.com/elpais/2017/07/25/estilo/1500992943_536176.html'],['Kohan · 2020','https://www.aacademica.org/000-007/483']]},
  {id:'talles',year:'2019',title:'La Ley de Talles en Argentina',summary:'La Ley 27.521 reconoce la necesidad de un sistema normalizado de talles.',body:'La demanda surge de una experiencia concreta: la ropa disponible no contempla la diversidad de cuerpos. La ley expresa un avance institucional; su sanción no significa que las experiencias de exclusión hayan desaparecido.',why:'El ideal corporal también se materializa en aquello que podemos —o no— encontrar en un local.',sources:[['Ley 27.521 · Boletín Oficial','https://www.boletinoficial.gob.ar/detalleAviso/primera/224023/20191220']]}
 ]},
 {id:'regreso',number:'04 / 04',title:'El mandato',accent:'se renueva.',lede:'No vuelve de forma idéntica: cambia de nombre, circula en nuevos formatos y comparte pantalla con sus propias críticas.',icon:'↻',aside:'La meta se mueve. La carrera vuelve a empezar.',events:[
  {id:'y2k',year:'2021–22',title:'Y2K y la vuelta de ciertas siluetas',summary:'La nostalgia por la moda de los 2000 convive con la predominancia de cuerpos delgados en pasarelas y campañas.',body:'Las prendas no pertenecen a un único tipo de cuerpo. El problema aparece cuando su representación se concentra en un ideal estrecho, incluso después de años de conversación sobre diversidad.',why:'Cuando la moda recicla una época, también puede reciclar el cuerpo que la acompañaba en las imágenes.',sources:[['El País · S Moda','https://elpais.com/smoda/moda/la-delgadez-extrema-vuelve-aduenarse-de-las-pasarelas-como-si-no-hubieramos-aprendido-nada.html']]},
  {id:'ozempic',year:'2022–23',title:'Ozempic entra en la conversación pública',summary:'Un medicamento para la diabetes se vuelve protagonista de debates mediáticos sobre pérdida de peso.',body:'Ozempic es una marca de semaglutida indicada para diabetes tipo 2 en diversos mercados; la conversación pública sobre sus efectos en el peso creció especialmente desde 2022. Este hito aborda su visibilidad mediática, sin presentar su uso médico y el deseo estético como si fueran lo mismo.',why:'Un producto de salud puede convertirse en símbolo cultural de una promesa corporal.',sources:[['El País · 2023','https://elpais.com/salud-y-bienestar/2023-03-29/ozempic-las-inyecciones-que-prometen-acabar-con-la-obesidad-arrasan-en-el-mercado-negro.html']]},
  {id:'silvina',year:'2023',title:'Silvina Luna: otra dimensión de la presión estética',summary:'Su muerte vuelve visible el debate argentino sobre intervenciones estéticas y mala praxis.',body:'Su historia no es un ejemplo de búsqueda de delgadez extrema: se incluye para abrir una dimensión relacionada, la presión por transformar el cuerpo y los riesgos de ciertas prácticas estéticas. Evitamos reducir su vida a una lección moral sobre las decisiones individuales.',why:'La conversación sobre el cuerpo también exige mirar el contexto, las promesas y las responsabilidades profesionales.',sources:[['La Nación · 31/08/2023','https://www.lanacion.com.ar/espectaculos/de-que-murio-silvina-luna-nid31082023/']]},
  {id:'wellness',year:'2023–26',title:'La delgadez con otras palabras',summary:'«Bienestar», «disciplina», «productividad» o «desinflamar» pueden volverse nuevas maneras de hablar del cuerpo.',body:'En videos What I Eat in a Day, contenidos de fitness o rutinas de cuidado, el ideal puede aparecer como una elección personal. No todo contenido de salud es un mandato de delgadez: la investigación pregunta cuándo el mensaje deja de hablar de bienestar y empieza a exigir una forma corporal.',why:'Cuando cambia el lenguaje, reconocer la presión se vuelve más difícil.',sources:[['El País · 2026','https://elpais.com/salud-y-bienestar/2026-03-26/la-vuelta-de-la-delgadez-extrema-disfrazada-de-salud-antes-te-decian-que-estabas-gorda-y-ahora-que-estas-inflamada.html'],['Infobae · 2026','https://www.infobae.com/salud/2026/04/13/la-obsesion-por-la-delgadez-adopta-nuevas-formas-en-la-cultura-fit-se-pueden-esconder-trastornos-alimentarios/']]},
  {id:'skinnytok',year:'2025',title:'El debate por #SkinnyTok',summary:'El hashtag reactiva la discusión sobre contenidos que promueven la delgadez en plataformas.',body:'TikTok confirmó en junio de 2025 el bloqueo global del hashtag. El episodio muestra que un mensaje puede mutar en etiquetas y formatos nuevos: la moderación de una palabra no agota un fenómeno cultural más amplio.',why:'El ideal cambia de formato tan rápido como cambia el lenguaje de las plataformas.',sources:[['El País · Opinión, 2025','https://elpais.com/opinion/2025-06-10/skinnytok-y-la-secta-del-no-eres-fea-solo-estas-gorda.html'],['Chequeado · redes y TCA','https://chequeado.com/el-explicador/trastornos-de-la-alimentacion-y-redes-sociales-los-mensajes-se-renuevan-y-se-adaptan-a-nuevos-y-peligrosos-hashtags-y-challenges/']]}
 ]}
];

const target=document.getElementById('timeline-body');
function make(tag,cls,txt){const el=document.createElement(tag);if(cls)el.className=cls;if(txt!==undefined)el.textContent=txt;return el}
for(const era of eras){const section=make('section','era-block');section.dataset.era=era.id;section.id='era-'+era.id;section.setAttribute('aria-labelledby','title-'+era.id);const inner=make('div','era-inner');const heading=make('div','era-heading');heading.append(make('span','era-count',era.number+' · ARCHIVO'),(()=>{const d=make('div');const h=make('h3');h.id='title-'+era.id;h.append(document.createTextNode(era.title+' '),make('span','',era.accent));d.append(h,make('p','era-lede',era.lede));return d})());inner.append(heading);const layout=make('div','event-layout');const aside=make('aside','event-aside');aside.append(make('span','aside-icon',era.icon),make('p','',era.aside));layout.append(aside);const list=make('div','event-list');for(const event of era.events){const card=make('article','event-card');card.id=event.id;const button=make('button','event-button');button.type='button';button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','detail-'+event.id);button.append(make('span','event-year',event.year),(()=>{const d=make('span');d.append(make('span','event-title',event.title),make('span','event-subtitle',event.summary));return d})(),make('span','event-toggle','+'));const detail=make('div','event-detail');detail.id='detail-'+event.id;detail.hidden=true;detail.append(make('p','',event.body),make('p','why',event.why));const links=make('div','source-links');for(const [label,url] of event.sources){const a=make('a','',label+' ↗');a.href=url;a.target='_blank';a.rel='noopener';links.append(a)}detail.append(links);button.addEventListener('click',()=>setOpen(card,!card.classList.contains('is-open'),true));card.append(button,detail);list.append(card)}layout.append(list);inner.append(layout);section.append(inner);target.append(section)}
function setOpen(card,open,updateHash=false){card.classList.toggle('is-open',open);card.querySelector('button').setAttribute('aria-expanded',String(open));card.querySelector('.event-detail').hidden=!open;if(updateHash&&open){history.replaceState(null,'','#'+card.id)}}
function openFromHash(){const id=decodeURIComponent(location.hash.slice(1));const card=document.getElementById(id);if(card?.classList.contains('event-card')){setOpen(card,true);requestAnimationFrame(()=>card.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}))}}
window.addEventListener('hashchange',openFromHash);if(location.hash)setTimeout(openFromHash,100);
const eraLinks=[...document.querySelectorAll('.era-nav a')];const observer=new IntersectionObserver(entries=>{const seen=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!seen)return;eraLinks.forEach(a=>a.classList.toggle('active',a.hash==='#'+seen.target.id))},{rootMargin:'-25% 0px -50% 0px',threshold:[0,.2,.5]});document.querySelectorAll('.era-block').forEach(e=>observer.observe(e));
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const photo=document.querySelector('.hero-photo');let pending=false;const onScroll=()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{photo.style.transform=`translate3d(0,${Math.min(window.scrollY,900)*.17}px,0)`;pending=false})};window.addEventListener('scroll',onScroll,{passive:true})}
